"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, pressScale, pressedOption } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Toggle classes: muted text in a rounded button, or a rounded button on a lilac track for `outline`, shown in the chosen-option tint when pressed. */
const toggleVariants = cva(
  [
    "inline-flex shrink-0 select-none items-center justify-center gap-1.5 whitespace-nowrap rounded-lg",
    "font-medium text-muted-foreground",
    pressScale,
    focusRing,
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    pressedOption,
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-transparent hover:not-data-[pressed]:text-foreground",
        outline: "bg-(--option-track) shadow-(--option-track-edge) hover:not-data-[pressed]:text-foreground",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4 text-sm",
        lg: "h-11 px-5 text-base",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/** Mallow Toggle on Base UI: one rounded button that stays pressed. */
const Toggle = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TogglePrimitive.Props> & VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive
    ref={ref}
    data-slot="toggle"
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
));
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
